import org.apache.commons.lang3.ArrayUtils;
import org.apache.spark.sql.Dataset;
import org.apache.spark.sql.Row;
import org.apache.spark.sql.SparkSession;

public class Main {
    public static void main(String[] args) {
        // Create a Spark session
        SparkSession spark = SparkSession.builder()
                .appName("Drop Columns from DataFrame")
                .getOrCreate();

        // Create a sample DataFrame
        Dataset<Row> df = spark.createDataFrame(
                new String[][]{
                        {"A", "B"},
                        {"C", "D"}
                },
                new String[]{"A", "B", "C"}
        );

        System.out.println("Original DataFrame:");
        df.show();

        // Drop specified columns from the DataFrame
        Dataset<Row> dropColumnsDF = dropColumns(df, new String[]{"A"});

        System.out.println("\nDataFrame after dropping specified columns:");
        dropColumnsDF.show();
    }

    public static Dataset<Row> dropColumns(Dataset<Row> df, String[] columnNames) {
        // Check if the column names exist in the DataFrame
        for (String columnName : columnNames) {
            boolean found = false;
            for (String[] columns : df.columns) {
                if (ArrayUtils.contains(columns, columnName)) {
                    found = true;
                    break;
                }
            }

            if (!found) {
                throw new RuntimeException("The specified column(s) '" + columnName + "' does not exist in the DataFrame.");
            }
        }

        // Return a new DataFrame with the specified columns removed
        return df.select(columnNames.length - 1);
    }
}
